def _parse(v):
    return tuple(int(x) for x in v.split("."))


def satisfies(version, rng):
    v = _parse(version)
    rng = rng.strip()
    if rng.startswith(">="):
        return v >= _parse(rng[2:])
    return v == _parse(rng.lstrip("="))

